clear;
close all;
clc;
thing = readtable("thing.csv");
% 30k samples for long period.
L = 30000;                      
F = [200, 400, 2000, 12500];
% match sample rate of system.
Fs = 48.8 * 10^3;


% samples will have 18-bit widths.
X_BITS = 18; 
FX_BITS = 18;
SHAT_SHIFT = 18;
OUTPUT_SHIFT = 21; 
% anti-noise output will have 32-bit width.
Y_BITS = 32;
WEIGHT_BITS = 26;
% static FIR accumulator bits.
ACC_BITS = 48;
% mu will be implemented as 2^-(this value)
mu = 2^(-10);



% this just clamps a value. Note that because this is 2's complement
% maximum values are 2^(b-1) - 1 and minimum is -2^(b-1)
sat  = @(v,b) max(min(v, 2^(b-1)-1), -2^(b-1)); 
% this just gets the integer and wraps it so it acts
% like a std_logic_vector. b is the number of bits, v is the value.
wrap = @(v,b) mod(v + 2^(b-1), 2^b) - 2^(b-1); 
% detect overflow based on if the value exceeds max or min value.
overflow = @(v,b) (v > 2^(b-1) - 1) | (v < -2^(b-1));

overflow_count = 0;

% generate input signal. round cuz ADC would do this and wrap to 18-bits.
x = sat(round(1000 * sin(F(4) / Fs * 2 * pi .* (1:L))), X_BITS);

s = thing.Format;
% take first 1024 elements in ROM.
s = s(1:1024); 
s = s(:).';
% the values above are in fixed-point, so just divide by however much its
% been shifted left by to get the true fractional values, otherwise
% convolving it with the antinoise will give BIG BOI gain.
s_true = s / 2^SHAT_SHIFT; 
s_num = length(s);

% weightings. these are 26-bit values.
w = zeros(1, 32);            
w_num = length(w);
% stores memory elements of x samples.
x_buff = zeros(1, max(w_num, s_num));
% same but for y.
y_buff = zeros(1, s_num);
% stores history of fx.
fx = zeros(1, w_num);
% stores history of y for graphing purposes.
y = zeros(1, L);
% same for graphing error.
e_arr = zeros(1, L);

for n = 1:L

    x_buff = [x(n), x_buff(1:end-1)];
%% STATIC FIR    
    acc = sum(x_buff(1:s_num) .* s);
    acc = wrap(acc, ACC_BITS);
    % calculate fx.
    fx  = [wrap(floor(acc / 2^SHAT_SHIFT), FX_BITS), fx(1:end-1)];
%% ADAPTIVE FIR
    % adaptive FIR uses only the top 26 bits of the accumulator. before
    % this line they are stored as 29-bit values.
    % w_out = floor(w / 2^WEIGHT_GUARD_BITS);
    w_out = floor(w);
    % convolve weights with history of x based on 32-tap FIR filter.
    yacc = sum(x_buff(1:w_num) .* w_out);
    % shift 49-bit accumulation down by 21-bits to get values. weights are
    % coincidentally 
    y(n) = sat(floor(yacc / 2^OUTPUT_SHIFT), Y_BITS);
    y_buff = [y(n), y_buff(1:end-1)];
%% COLLISION
    % simulated speaker -> mic path
    ys = sum(y_buff .* s_true);
    e = sat(round(x(n) + ys), X_BITS);
    e_arr(n) = e;
%% FXLMS WEGIHT UPDATING
    % weight update, accumulator wraps at WA bits
    % w = wrap(w - floor(e .* fx .* mu), WEIGHT_TRUE_BITS);
    w = w - floor(e .* fx .* mu);
    if any(overflow(w, WEIGHT_BITS))
        overflow_count = overflow_count + 1;
    end
    w = wrap(w, WEIGHT_BITS);
end

overflow_count %[output:34725d87]
figure;  %[output:27752ee7]
plot(e_arr);  %[output:27752ee7]
title("Error"); %[output:27752ee7]
xlabel("Sample"); %[output:27752ee7]
ylabel("Amplitude"); %[output:27752ee7]
ylim([min(e_arr), max(e_arr)]); %[output:27752ee7]

figure;  %[output:3d3081fe]
subplot(2, 1, 1); %[output:3d3081fe]
plot(y);      %[output:3d3081fe]
title("Anti Noise"); %[output:3d3081fe]
xlabel("Sample"); %[output:3d3081fe]
ylabel("Amplitude"); %[output:3d3081fe]
ylim([-2000, 2000]); %[output:3d3081fe]

subplot(2, 1, 2); %[output:3d3081fe]
plot(x); %[output:3d3081fe]
title("Input Noise"); %[output:3d3081fe]
xlabel("Sample"); %[output:3d3081fe]
ylabel("Amplitude"); %[output:3d3081fe]
ylim([-2000, 2000]); %[output:3d3081fe]
    

